  vim.api.nvim_set_hl(0, "MatchParen", { fg = "#509475", bg = "#23372b" })
end

local group = vim.api.nvim_create_augroup("ThemePickerPalette", { clear = true })
vim.api.nvim_create_autocmd("ColorScheme", { group = group, callback = apply_theme_picker_theme })
vim.api.nvim_create_autocmd("VimEnter", { group = group, callback = apply_theme_picker_theme })
vim.api.nvim_create_autocmd("User", { group = group, pattern = "VeryLazy", callback = apply_theme_picker_theme })
apply_theme_picker_theme()
vim.schedule(apply_theme_picker_theme)
